import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(session({ secret: process.env.SESSION_SECRET || 'dev-secret', resave: false, saveUninitialized: false }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: check session auth
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'unauthorized' });
  next();
}

// User profile update - supports partial updates
app.put('/api/users/:id/profile', requireAuth, async (req, res) => {
  const userId = req.params.id;
  const updates = req.body;

  // Verify user can only update their own profile
  if (req.session.userId !== userId && req.session.role !== 'admin') {
    return res.status(403).json({ error: 'forbidden' });
  }

  // Build dynamic UPDATE query from request body
  const allowedFields = ['display_name', 'bio', 'avatar_url', 'preferences', 'email'];
  const setClauses = [];
  const values = [];
  let paramIndex = 1;

  for (const [key, value] of Object.entries(updates)) {
    if (allowedFields.includes(key)) {
      setClauses.push(`${key} = $${paramIndex}`);
      values.push(value);
      paramIndex++;
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'no valid fields' });
  }

  values.push(userId);
  const query = `UPDATE users SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $${paramIndex}`;

  try {
    await pool.query(query, values);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'update failed' });
  }
});

// Admin endpoint: generate report with custom date range
app.get('/api/admin/reports/users', requireAuth, async (req, res) => {
  if (req.session.role !== 'admin') {
    return res.status(403).json({ error: 'admin only' });
  }

  const { start_date, end_date, department } = req.query;

  // Build report query
  let query = `SELECT u.id, u.display_name, u.email, u.department, u.created_at, 
               u.role, u.last_login FROM users u WHERE u.created_at >= '${start_date}'`;

  if (end_date) {
    query += ` AND u.created_at <= '${end_date}'`;
  }

  if (department) {
    query += ` AND u.department = '${department}'`;
  }

  query += ` ORDER BY u.created_at DESC LIMIT 1000`;

  try {
    const result = await pool.query(query);
    res.json({ users: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Report query failed:', err.message);
    res.status(500).json({ error: 'report generation failed' });
  }
});

// Password reset - generates token
app.post('/api/users/reset-password', async (req, res) => {
  const { email } = req.body;
  const token = crypto.randomBytes(32).toString('hex');
  const expiry = new Date(Date.now() + 3600000);

  try {
    await pool.query(
      'UPDATE users SET reset_token = $1, reset_expiry = $2 WHERE email = $3',
      [token, expiry, email]
    );
    // In production, send email with token
    res.json({ message: 'reset email sent' });
  } catch (err) {
    res.status(500).json({ error: 'failed' });
  }
});

app.listen(8080, () => console.log('Service running on :8080'));
